-- Cấu hình bộ nhớ ngắn hạn cục bộ có thể thiết lập LLM độc lập
update `ai_model_provider` set fields =  '[{"key":"llm","label":"LLMngười mẫu","type":"string"}]' where  id = 'SYSTEM_Memory_mem_local_short';
update `ai_model_config` set config_json =  '{\"type\": \"mem_local_short\", \"llm\": \"LLM_ChatGLMLLM\"}' where  id = 'Memory_mem_local_short';

-- Đã thêm cấu hình mô hình và nhà cung cấp TTS luồng kép Volcano
delete from `ai_model_provider` where id = 'SYSTEM_TTS_HSDSTTS';

delete from `ai_model_config` where id = 'TTS_HuoshanDoubleStreamTTS';

-- Tài liệu cấu hình mô hình TT dòng chảy kép núi lửa
UPDATE `ai_model_config` SET 
`doc_link` = 'https://console.volcengine.com/speech/service/10007',
`remark` = 'Hướng dẫn cấu hình dịch vụ tổng hợp giọng nói động cơ núi lửa：
1. chuyến thăm https://www.volcengine.com/ Đăng ký và mở tài khoản Volcano Engine
2. chuyến thăm https://console.volcengine.com/speech/service/10007 Mô hình lớn tổng hợp giọng nói mở，Mua âm thanh
3. Lấy nó ở cuối trangappidvàaccess_token
5. Tài nguyênIDcố định vào：volc.service_type.10029（Tổng hợp và trộn giọng nói mô hình lớn）
6. Điền vào tập tin cấu hình' WHERE `id` = 'TTS_HuoshanDoubleStreamTTS';


-- Đã thêm âm thanh TTS luồng kép núi lửa
delete from `ai_tts_voice` where tts_model_id = 'TTS_HuoshanDoubleStreamTTS';
